if (saved) {
  $('#text').value = saved.text ?? $('#text').value;
  $('#color').value = saved.color ?? $('#color').value;
  $('#angle').value = String(saved.angle ?? 45);
  $('#opacity').value = String(saved.opacity ?? 0.2);
  $('#pages').value = saved.pages ?? '';
}
refresh();
